# List all instances to identify shapes and slots
result = primitives.call('list_maniskill_instances', camera_uid='base_camera', min_pixel_count=50)
print(f"List instances ok={result.ok}")
if result.ok:
    print(f"Output type: {type(result.output)}")
    print(f"Output: {result.output}")
    instances = result.output
    if isinstance(instances, list):
        print(f"Found {len(instances)} instances")
        for inst in instances:
            if isinstance(inst, dict):
                print(f"  ID={inst.get('segmentation_id')}, pixels={inst.get('pixel_count')}, depth={inst.get('depth')}")
            else:
                print(f"  Instance: {inst}")
    else:
        print(f"Instances is not a list: {instances}")

# Also check hand camera
result = primitives.call('list_maniskill_instances', camera_uid='hand_camera', min_pixel_count=50)
print(f"Hand camera instances ok={result.ok}")
if result.ok:
    print(f"Output type: {type(result.output)}")
    print(f"Output: {result.output}")
